def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        new_grid = grid.copy()
        mask = (new_grid == 14)
        if np.any(mask):
            center_row = np.argmax(mask, axis=1).flatten()
            center_col = np.argmax(mask, axis=0).flatten()
            if row is not None and col is not None:
                new_grid[row, col] = 10
                new_grid[center_row, center_col] = 14
        return {"next_grid": new_grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {"target_row": row, "target_col": col}}
    else:
        return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

