    grid = frames[-1]
    palette = np.unique(grid)
    target = 14
    if target not in palette:
        return 0.0
    count_target = np.count_nonzero(grid == target)
    count_blue = np.count_nonzero(grid == 9)
    if count_blue == 0:
        return 0.0
    return count_target / float(count_blue)

