def predict(history, action):
    grid = np.array(history.frames[-1], dtype=np.int8)
    kind = int(action.kind)
    if kind == 6:
        row = int(action.row)
        col = int(action.col)
        frame = grid.copy()
        frame[row, col] = 14
        return {"next_grid": frame, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {"target_cell": [row, col]}}
    else:
        return {"next_grid": grid, "game_state": "NOT_FINISHED", "level_delta": 0, "memory": {}}

def goal_value(history):
    frame = history.frames[-1]
    palette = np.unique(frame)
    blue_cells = np.count_nonzero(frame == 9)
    if blue_cells == 0:
        return 0.0
    green_cells = np.count_nonzero(frame == 14)
    total_green = np.sum(green_cells) if green_cells > 0 else 1
    return min(1.0, blue_cells / total_green)
